package change

import (
	"bytes"
	"errors"
	"reflect"
	"testing"

	"github.com/georgejieh/open-trestle/artifact"
	"github.com/georgejieh/open-trestle/internal/changecodec"
	"github.com/georgejieh/open-trestle/internal/evidence"
	"github.com/georgejieh/open-trestle/internal/sourceoutput"
)

// The fixture is generated by the real source and change handlers, not from a wire-only stub.
func TestLowerChangeCodecMatchesFacadeAndTypedConstructor(t *testing.T) {
	output, base, head, _, _ := realChangeFixture(t)
	lowerBase, lowerHead, lowerErr := changecodec.ResultArtifactReferences(output)
	upperBase, upperHead, upperErr := ResultArtifactReferences(output)
	if lowerErr != nil || upperErr != nil || lowerBase != upperBase || lowerHead != upperHead || lowerBase != base.Identity() || lowerHead != head.Identity() {
		t.Fatalf("references lower=(%s,%s,%v) facade=(%s,%s,%v)", lowerBase, lowerHead, lowerErr, upperBase, upperHead, upperErr)
	}
	lower, lowerErr := changecodec.ParseResultArtifact(output, base, head)
	upper, upperErr := ParseResultArtifact(output, base, head)
	if lowerErr != nil || upperErr != nil || !reflect.DeepEqual(lower, upper) || lower.Identity() != "4c765836bb0d985a6a99596a3e8b3ef37083fe88cf1458f54717b34c3d471884" || lower.ArtifactIdentity() != output.Identity() || lower.BaseSnapshotIdentity() != upper.BaseSnapshotIdentity() || lower.HeadSnapshotIdentity() != upper.HeadSnapshotIdentity() || lower.Repository().Identity() != upper.Repository().Identity() || !reflect.DeepEqual(lower.Entries(), upper.Entries()) {
		t.Fatalf("parse lower=(%s,%v) facade=(%s,%v)", lower.Identity(), lowerErr, upper.Identity(), upperErr)
	}
	for _, pair := range [][2]artifact.Artifact{{output, head}, {artifact.Artifact{}, head}} {
		_, lowerErr = changecodec.ParseResultArtifact(output, pair[0], pair[1])
		_, upperErr = ParseResultArtifact(output, pair[0], pair[1])
		if !errors.Is(lowerErr, changecodec.ErrInvalidResult) || !errors.Is(upperErr, ErrInvalidResult) {
			t.Fatalf("negative parse lower=%v facade=%v", lowerErr, upperErr)
		}
	}
	_, _, lowerErr = changecodec.ResultArtifactReferences(base)
	_, _, upperErr = ResultArtifactReferences(base)
	if !errors.Is(lowerErr, changecodec.ErrInvalidResult) || !errors.Is(upperErr, ErrInvalidResult) {
		t.Fatalf("negative references lower=%v facade=%v", lowerErr, upperErr)
	}

	baseSnapshot, err := sourceoutput.ParseSnapshotArtifact(base)
	if err != nil {
		t.Fatal(err)
	}
	headSnapshot, err := sourceoutput.ParseSnapshotArtifact(head)
	if err != nil {
		t.Fatal(err)
	}
	manifest := func(contents map[string]string) evidence.RepositoryManifest {
		t.Helper()
		files := make([]evidence.RepositoryFile, 0, len(contents))
		for path, content := range contents {
			file, err := evidence.NewRepositoryFile(path, []byte(content))
			if err != nil {
				t.Fatal(err)
			}
			files = append(files, file)
		}
		value, err := evidence.NewRepositoryManifest(files)
		if err != nil {
			t.Fatal(err)
		}
		return value
	}
	baseFiles := map[string]string{"a.txt": "old\n", "removed.txt": "gone\n"}
	headFiles := map[string]string{"a.txt": "new\n", "added.txt": "hello\n"}
	delta, err := evidence.NewRepositoryManifestDelta(manifest(baseFiles), manifest(headFiles))
	if err != nil {
		t.Fatal(err)
	}
	if delta.Identity() != lower.DeltaIdentity() {
		t.Fatalf("fixture delta identity=%s", delta.Identity())
	}
	deltaEntries := delta.Entries()
	executions := make([]evidence.RepositoryFileDeltaExecution, len(deltaEntries))
	for index, entry := range deltaEntries {
		baseContent := evidence.RepositoryFileDeltaContent{}
		headContent := evidence.RepositoryFileDeltaContent{}
		if content, ok := baseFiles[entry.Path()]; ok {
			baseContent = evidence.RepositoryFileDeltaContent{Present: true, Content: []byte(content)}
		}
		if content, ok := headFiles[entry.Path()]; ok {
			headContent = evidence.RepositoryFileDeltaContent{Present: true, Content: []byte(content)}
		}
		executions[index], err = evidence.ExecuteRepositoryFileDelta(entry, baseContent, headContent)
		if err != nil {
			t.Fatal(err)
		}
	}
	construct := func(executions []evidence.RepositoryFileDeltaExecution, extra map[string][]evidence.SourceRange) (changecodec.Result, error) {
		return changecodec.NewResult(base, head, baseSnapshot, headSnapshot, lower.Repository(), lower.BaseRevision(), lower.HeadRevision(), delta, executions, extra)
	}
	direct, err := construct(executions, nil)
	if err != nil || direct.Identity() != lower.Identity() {
		t.Fatalf("constructor identity=%s err=%v", direct.Identity(), err)
	}
	payload, err := changecodec.EncodeResult(direct)
	if err != nil || !bytes.Equal(payload, output.Payload()) || string(payload) != oldCodeChangePayload {
		t.Fatalf("direct payload mismatch: %v", err)
	}
	if _, err := changecodec.EncodeResult(changecodec.Result{}); !errors.Is(err, changecodec.ErrInvalidResult) {
		t.Fatalf("zero encode=%v", err)
	}
	reversed := append([]evidence.RepositoryFileDeltaExecution(nil), executions...)
	reversed[0], reversed[1] = reversed[1], reversed[0]
	if _, err := construct(reversed, nil); !errors.Is(err, changecodec.ErrInvalidResult) {
		t.Fatalf("reordered execution=%v", err)
	}
	extraRange, err := evidence.NewSourceRange("wrong.txt", 1, 1)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := construct(executions, map[string][]evidence.SourceRange{"removed.txt": {extraRange}}); !errors.Is(err, changecodec.ErrInvalidResult) {
		t.Fatalf("wrong-path extra range=%v", err)
	}
	if _, err := construct(executions, map[string][]evidence.SourceRange{"unknown.txt": {extraRange}}); !errors.Is(err, changecodec.ErrInvalidResult) {
		t.Fatalf("uncovered extra range=%v", err)
	}
	if _, err := changecodec.NewResult(head, base, baseSnapshot, headSnapshot, lower.Repository(), lower.BaseRevision(), lower.HeadRevision(), delta, executions, nil); !errors.Is(err, changecodec.ErrInvalidResult) {
		t.Fatalf("wrong snapshot artifact=%v", err)
	}
}
